@startuml

class Customer {
  + name : string
  + surname : string
  + email : string
  + telephone : string
  + homeAddress : string
}

class Order {
  + totalCost : double
  + estimatedDeliveryTime : time
  + status : string
}

class Dish {
  + name : string
}

class Payment {
  + status : string
}

class Kitchen {
  + workload : int
}

class Delivery {
  + status : string
}

Customer "1" -- "*" Order : places
Order "1" -- "1..*" Dish : contains
Order "1" -- "0..1" Payment : processed by
Order "1" -- "0..1" Kitchen : assigned to
Order "1" -- "0..1" Delivery : fulfilled by

@enduml

